def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {OR IGNORE, OR REPLACE, ON CONFLICT DO UPDATE}
    # channel in {changes(), total_changes(main), total_changes(main)+total_changes(other)}
    # trigger: none or one AFTER INSERT inserting one row into aux log
    # We simulate all 18 members and keep those consistent with history.

    def simulate(put_mode, chan_mode, trig, actions):
        # returns (channel, committed_count, committed_sum)
        # state: dict key->value for committed; pending per connection
        committed = {}
        # transaction state per connection: None or dict of pending ops
        # We model simply: each connection has its own uncommitted overlay
        # main and other each may have an open transaction
        tx = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # changes() is per-connection last statement direct change count
        last_changes = {"main": 0, "other": 0}
        # aux log count (unread, but trigger fires)
        aux = 0

        def apply_put(conn, key, value):
            nonlocal aux
            # determine current visible value for this connection
            base = committed
            overlay = tx[conn]
            if overlay is not None:
                cur = overlay.get(key, base.get(key, None))
            else:
                cur = base.get(key, None)
            changed = 0
            if put_mode == "ignore":
                if cur is None:
                    changed = 1
                    if overlay is not None:
                        overlay[key] = value
                    else:
                        committed[key] = value
            elif put_mode == "replace":
                if cur is None or cur != value:
                    changed = 1
                    if overlay is not None:
                        overlay[key] = value
                    else:
                        committed[key] = value
                else:
                    # REPLACE deletes and reinserts even if same value -> row change
                    changed = 1
                    if overlay is not None:
                        overlay[key] = value
                    else:
                        committed[key] = value
            else:  # upsert
                if cur is None:
                    changed = 1
                    if overlay is not None:
                        overlay[key] = value
                    else:
                        committed[key] = value
                elif cur != value:
                    changed = 1
                    if overlay is not None:
                        overlay[key] = value
                    else:
                        committed[key] = value
                else:
                    changed = 0
            if changed and trig:
                aux += 1
            return changed

        def apply_update(conn, key, value):
            nonlocal aux
            base = committed
            overlay = tx[conn]
            if overlay is not None:
                cur = overlay.get(key, base.get(key, None))
            else:
                cur = base.get(key, None)
            if cur is None:
                return 0
            if cur == value:
                return 0
            if overlay is not None:
                overlay[key] = value
            else:
                committed[key] = value
            return 1

        def apply_delete(conn, key):
            base = committed
            overlay = tx[conn]
            if overlay is not None:
                cur = overlay.get(key, base.get(key, None))
            else:
                cur = base.get(key, None)
            if cur is None:
                return 0
            if overlay is not None:
                if key in overlay:
                    del overlay[key]
                else:
                    overlay[key] = None  # tombstone
            else:
                del committed[key]
            return 1

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                c = apply_put(conn, act["key"], act["value"])
                last_changes[conn] = c
                tc[conn] += c
            elif op == "update":
                c = apply_update(conn, act["key"], act["value"])
                last_changes[conn] = c
                tc[conn] += c
            elif op == "delete":
                c = apply_delete(conn, act["key"])
                last_changes[conn] = c
                tc[conn] += c
            elif op == "begin":
                tx[conn] = {}
                last_changes[conn] = 0
            elif op == "commit":
                overlay = tx[conn]
                if overlay is not None:
                    for k, v in overlay.items():
                        if v is None:
                            if k in committed:
                                del committed[k]
                        else:
                            committed[k] = v
                tx[conn] = None
                last_changes[conn] = 0
            elif op == "rollback":
                tx[conn] = None
                last_changes[conn] = 0

        if chan_mode == "changes":
            channel = last_changes["main"]
        elif chan_mode == "total_main":
            channel = tc["main"]
        else:
            channel = tc["main"] + tc["other"]
        return channel, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    chan_modes = ["changes", "total_main", "total_both"]
    trigs = [False, True]

    candidates = []
    for pm in put_modes:
        for cm in chan_modes:
            for tg in trigs:
                ok = True
                for rec in hist:
                    ch, cc, cs = simulate(pm, cm, tg, rec["actions"])
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tg))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for pm, cm, tg in candidates:
        ch, cc, cs = simulate(pm, cm, tg, actions)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
